insert into public.enneagram_profiles (key, content, version) values
('1', '{"key":"1","type":1,"wing":null,"title":"더 나은 내일을 만드는 사람","description":"원칙과 개선에 마음이 향하는 패턴입니다. 꼼꼼함이 힘이 되지만, 충분히 잘한 순간에도 고칠 점부터 찾을 수 있습니다.","advice":["오늘 할 일 하나에 충분함의 기준을 먼저 정해 보세요.","잘못한 점과 함께 잘 지킨 가치도 적어 보세요.","쉬는 시간을 다음 일을 위한 자격 심사 없이 마련해 보세요."]}'::jsonb, 1),
('1w9', '{"key":"1w9","type":1,"wing":9,"title":"차분하게 다듬는 이상","description":"개선하려는 마음에 차분한 조율이 더해질 수 있습니다.","advice":["평온을 유지하는 것과 필요한 의견을 말하는 것을 함께 연습해 보세요.","오늘 할 일 하나에 충분함의 기준을 먼저 정해 보세요.","바로 고치기 전에 상대가 조언을 원하는지 물어보세요."]}'::jsonb, 1),
('1w2', '{"key":"1w2","type":1,"wing":2,"title":"돌봄으로 실천하는 원칙","description":"개선하려는 마음이 사람을 돕는 행동으로 나타날 수 있습니다.","advice":["좋은 의도와 상대가 실제로 원하는 도움을 구분해 보세요.","오늘 할 일 하나에 충분함의 기준을 먼저 정해 보세요.","바로 고치기 전에 상대가 조언을 원하는지 물어보세요."]}'::jsonb, 1),
('2', '{"key":"2","type":2,"wing":null,"title":"마음을 잇는 다정한 사람","description":"관계와 돌봄에 마음이 향하는 패턴입니다. 필요한 것을 잘 알아차리지만, 남을 살피다가 자신의 필요를 뒤로 미룰 수 있습니다.","advice":["남을 돕기 전에 지금 나의 여유를 확인해 보세요.","오늘 필요한 것 하나를 직접 부탁해 보세요.","도움을 주지 않는 시간에도 이어지는 관계를 떠올려 보세요."]}'::jsonb, 1),
('2w1', '{"key":"2w1","type":2,"wing":1,"title":"성실하게 건네는 다정함","description":"관계를 돌보는 마음에 책임과 원칙이 더해질 수 있습니다.","advice":["도움이 의무처럼 느껴질 때 자신의 여유도 확인해 보세요.","남을 돕기 전에 지금 나의 여유를 확인해 보세요.","도움을 건네기 전에 필요한 방식부터 물어보세요."]}'::jsonb, 1),
('2w3', '{"key":"2w3","type":2,"wing":3,"title":"사람을 모으는 온기","description":"관계를 돌보는 마음이 활발한 연결과 실행으로 나타날 수 있습니다.","advice":["좋은 반응을 얻는 모습 뒤의 내 필요도 말해 보세요.","남을 돕기 전에 지금 나의 여유를 확인해 보세요.","도움을 건네기 전에 필요한 방식부터 물어보세요."]}'::jsonb, 1),
('3', '{"key":"3","type":3,"wing":null,"title":"가능성을 현실로 옮기는 사람","description":"목표와 성취에 마음이 향하는 패턴입니다. 실행과 적응에 강하지만, 성과를 자신의 가치와 너무 가까이 묶을 수 있습니다.","advice":["평가받지 않는 즐거움에 시간을 써 보세요.","이번 목표가 누구의 기대에서 시작됐는지 적어 보세요.","오늘의 기분을 실적과 별개로 한 문장 남겨 보세요."]}'::jsonb, 1),
('3w2', '{"key":"3w2","type":3,"wing":2,"title":"함께 빛나는 실행","description":"성취하려는 마음에 사람들과 연결하는 힘이 더해질 수 있습니다.","advice":["기대에 부응하는 목표와 내가 원하는 목표를 나누어 보세요.","평가받지 않는 즐거움에 시간을 써 보세요.","대화에서 해결할 일과 함께 감정을 물어보세요."]}'::jsonb, 1),
('3w4', '{"key":"3w4","type":3,"wing":4,"title":"나의 색을 담은 성취","description":"성취하려는 마음이 자신만의 표현과 결합할 수 있습니다.","advice":["비교에서 잠시 벗어나 과정에서 만족한 순간을 찾아보세요.","평가받지 않는 즐거움에 시간을 써 보세요.","대화에서 해결할 일과 함께 감정을 물어보세요."]}'::jsonb, 1),
('4', '{"key":"4","type":4,"wing":null,"title":"나만의 색으로 느끼는 사람","description":"정체성과 감정의 의미에 마음이 향하는 패턴입니다. 섬세한 표현이 힘이 되지만, 비교 속에서 자신에게 없는 것에 집중할 수 있습니다.","advice":["기분이 준비되기 전에 작은 일 하나를 시작해 보세요.","현재 곁에 있는 좋은 것 세 가지를 구체적으로 적어 보세요.","느낌과 그 느낌에 붙인 해석을 나누어 적어 보세요."]}'::jsonb, 1),
('4w3', '{"key":"4w3","type":4,"wing":3,"title":"세상에 전하는 나의 색","description":"고유함을 표현하려는 마음에 실행과 전달의 힘이 더해질 수 있습니다.","advice":["표현에 대한 평가와 표현 자체의 의미를 나누어 보세요.","기분이 준비되기 전에 작은 일 하나를 시작해 보세요.","상대가 알아주길 기다리는 마음을 말로 전해 보세요."]}'::jsonb, 1),
('4w5', '{"key":"4w5","type":4,"wing":5,"title":"깊이 탐색하는 마음","description":"고유함을 찾으려는 마음에 조용한 탐구가 더해질 수 있습니다.","advice":["내면에서 발견한 것을 작은 대화나 행동으로 연결해 보세요.","기분이 준비되기 전에 작은 일 하나를 시작해 보세요.","상대가 알아주길 기다리는 마음을 말로 전해 보세요."]}'::jsonb, 1),
('5', '{"key":"5","type":5,"wing":null,"title":"깊이 바라보고 이해하는 사람","description":"이해와 지식, 자신의 여유를 지키는 데 마음이 향하는 패턴입니다. 깊게 탐구하지만, 준비가 끝나기를 기다리며 참여를 미룰 수 있습니다.","advice":["더 조사하기 전에 작게 시험할 행동을 정해 보세요.","하루 한 번 생각을 멈추고 몸의 상태를 살펴보세요.","혼자만 이해한 내용을 짧게 나누어 보세요."]}'::jsonb, 1),
('5w4', '{"key":"5w4","type":5,"wing":4,"title":"상상으로 여는 탐구","description":"이해하려는 마음이 자신만의 감성과 상상으로 확장될 수 있습니다.","advice":["생각 속에서 정리한 아이디어를 짧은 실험으로 꺼내 보세요.","더 조사하기 전에 작게 시험할 행동을 정해 보세요.","혼자 있을 시간이 필요하면 돌아올 시점도 알려 주세요."]}'::jsonb, 1),
('5w6', '{"key":"5w6","type":5,"wing":6,"title":"차근차근 검증하는 탐구","description":"이해하려는 마음에 대비와 검증이 더해질 수 있습니다.","advice":["지금 충분히 아는 범위를 정하고 작게 시작해 보세요.","더 조사하기 전에 작게 시험할 행동을 정해 보세요.","혼자 있을 시간이 필요하면 돌아올 시점도 알려 주세요."]}'::jsonb, 1),
('6', '{"key":"6","type":6,"wing":null,"title":"함께할 길을 단단히 지키는 사람","description":"안전과 신뢰할 기반에 마음이 향하는 패턴입니다. 대비와 협력에 강하지만, 가능성을 점검하다가 자신의 판단까지 의심할 수 있습니다.","advice":["지금 확인된 사실과 예상하는 일을 구분해 보세요.","작은 결정 하나는 정한 시점에 마무리해 보세요.","불안 속에서도 잘 대응했던 경험을 적어 보세요."]}'::jsonb, 1),
('6w5', '{"key":"6w5","type":6,"wing":5,"title":"생각으로 다지는 신뢰","description":"안전한 기반을 찾는 마음에 분석과 독립적인 검토가 더해질 수 있습니다.","advice":["조사의 종료 기준을 정하고 내 판단을 한 번 실행해 보세요.","지금 확인된 사실과 예상하는 일을 구분해 보세요.","신뢰를 시험하는 질문 대신 필요한 확신을 직접 요청해 보세요."]}'::jsonb, 1),
('6w7', '{"key":"6w7","type":6,"wing":7,"title":"함께 넓히는 용기","description":"안전한 기반을 찾는 마음에 밝은 연결과 가능성이 더해질 수 있습니다.","advice":["함께하는 즐거움 속에서도 우려를 구체적인 말로 전해 보세요.","지금 확인된 사실과 예상하는 일을 구분해 보세요.","신뢰를 시험하는 질문 대신 필요한 확신을 직접 요청해 보세요."]}'::jsonb, 1),
('7', '{"key":"7","type":7,"wing":null,"title":"새로운 가능성을 발견하는 사람","description":"가능성과 자유로운 경험에 마음이 향하는 패턴입니다. 밝은 아이디어가 힘이 되지만, 불편한 감정이나 한계를 새 계획으로 덮을 수 있습니다.","advice":["새 계획을 추가하기 전에 하나를 끝내 보세요.","아쉬운 마음을 바로 긍정으로 바꾸지 않고 잠시 들어 보세요.","오늘의 즐거움 하나를 다른 활동 없이 충분히 느껴 보세요."]}'::jsonb, 1),
('7w6', '{"key":"7w6","type":7,"wing":6,"title":"함께 떠나는 발견","description":"경험을 넓히려는 마음에 동료와 계획을 챙기는 힘이 더해질 수 있습니다.","advice":["모두를 위한 계획에 내 시간과 한계도 넣어 보세요.","새 계획을 추가하기 전에 하나를 끝내 보세요.","상대가 힘들 때 즐거운 제안보다 먼저 이야기를 들어 주세요."]}'::jsonb, 1),
('7w8', '{"key":"7w8","type":7,"wing":8,"title":"과감하게 여는 가능성","description":"경험을 넓히려는 마음에 주도적인 실행이 더해질 수 있습니다.","advice":["빠르게 정하기 전에 함께하는 사람의 속도도 물어보세요.","새 계획을 추가하기 전에 하나를 끝내 보세요.","상대가 힘들 때 즐거운 제안보다 먼저 이야기를 들어 주세요."]}'::jsonb, 1),
('8', '{"key":"8","type":8,"wing":null,"title":"소중한 것을 지키며 나아가는 사람","description":"자율성과 보호할 힘에 마음이 향하는 패턴입니다. 단호한 결단이 힘이 되지만, 자신을 지키려는 강도가 상대에게 압박으로 닿을 수 있습니다.","advice":["결정 전에 지금의 강도가 필요한지 한 번 확인해 보세요.","믿을 만한 사람에게 작은 도움을 요청해 보세요.","통제할 일과 함께 맡겨도 되는 일을 구분해 보세요."]}'::jsonb, 1),
('8w7', '{"key":"8w7","type":8,"wing":7,"title":"활기 있게 나아가는 용기","description":"자율성을 지키려는 마음에 새로운 시도와 활기가 더해질 수 있습니다.","advice":["추진할 에너지와 마무리할 여유를 함께 계산해 보세요.","결정 전에 지금의 강도가 필요한지 한 번 확인해 보세요.","솔직한 말이 상대에게 어떻게 들렸는지 물어보세요."]}'::jsonb, 1),
('8w9', '{"key":"8w9","type":8,"wing":9,"title":"차분하게 지키는 힘","description":"자율성을 지키려는 마음에 안정과 조율이 더해질 수 있습니다.","advice":["조용히 버티기보다 원하는 변화와 이유를 말해 보세요.","결정 전에 지금의 강도가 필요한지 한 번 확인해 보세요.","솔직한 말이 상대에게 어떻게 들렸는지 물어보세요."]}'::jsonb, 1),
('9', '{"key":"9","type":9,"wing":null,"title":"서로의 사이에 여유를 만드는 사람","description":"평온과 연결을 유지하는 데 마음이 향하는 패턴입니다. 서로의 입장을 잘 받아들이지만, 조화를 지키며 자신의 바람을 흐리게 할 수 있습니다.","advice":["다른 의견을 듣기 전에 내 바람을 적어 보세요.","미뤄 둔 일 하나를 5분만 시작해 보세요.","작은 불편도 알아차린 순간 이름을 붙여 보세요."]}'::jsonb, 1),
('9w8', '{"key":"9w8","type":9,"wing":8,"title":"부드럽게 지키는 경계","description":"평온을 지키려는 마음에 소중한 것을 보호하는 힘이 더해질 수 있습니다.","advice":["평소에도 작은 경계를 알려 갑작스러운 강한 반응을 줄여 보세요.","다른 의견을 듣기 전에 내 바람을 적어 보세요.","동의하는 부분과 다른 부분을 함께 말해 보세요."]}'::jsonb, 1),
('9w1', '{"key":"9w1","type":9,"wing":1,"title":"성실하게 가꾸는 평온","description":"평온을 지키려는 마음에 원칙과 성실함이 더해질 수 있습니다.","advice":["해야 할 일 목록에 내가 하고 싶은 일도 한 가지 넣어 보세요.","다른 의견을 듣기 전에 내 바람을 적어 보세요.","동의하는 부분과 다른 부분을 함께 말해 보세요."]}'::jsonb, 1)
